def transform2(g):
 o=[r[:] for r in g]; from collections import defaultdict
 rows=defaultdict(list); cols=defaultdict(list)
 for i,row in enumerate(g):
  for j,v in enumerate(row):
   if v==9: rows[i].append(j); cols[j].append(i)
 for d,axis in ((rows,0),(cols,1)):
  for key, vals in d.items():
   vals=sorted(set(vals))
   for a,b in zip(vals,vals[1:]):
    if b-a<=8:
     for x in range(a+1,b):
      (o[key].__setitem__(x,2) if axis==0 else o[x].__setitem__(key,2))
 return o
